<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/safety_vote_phase6.php';

function sv6_campaign(int$id,bool$lock=false):?array{return db_row("SELECT c.*,v.VersionNo,v.CampaignType,v.PrivacyMode,v.ResultVisibility,v.Status VersionStatus FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?".($lock?' FOR UPDATE':''),[$id]);}
function sv6_election_input(array$c):array{$positions=db_rows('SELECT * FROM SafetyVote_ElectionPositions WHERE CampaignVersionID=? ORDER BY SortOrder,id',[$c['CurrentVersionID']]);foreach($positions as&$p){$p=['positionCode'=>$p['PositionCode'],'questionId'=>(int)$p['QuestionID'],'title'=>$p['Title'],'seatCount'=>(int)$p['SeatCount'],'maxSelections'=>(int)$p['MaxSelections'],'allowAbstain'=>(bool)$p['AllowAbstain'],'tieRule'=>$p['TieRule'],'sortOrder'=>(int)$p['SortOrder'],'candidateIds'=>array_map(fn($x)=>(int)$x['CandidateID'],db_rows('SELECT CandidateID FROM SafetyVote_ElectionPositionCandidates WHERE PositionID=? ORDER BY SortOrder,CandidateID',[$p['id']]))];}unset($p);$counts=db_rows("SELECT ep.PositionCode positionCode,c.id candidateId,0 abstain,COUNT(*) count FROM SafetyVote_ElectionPositions ep JOIN SafetyVote_ElectionPositionCandidates epc ON epc.PositionID=ep.id JOIN SafetyVote_Candidates c ON c.id=epc.CandidateID JOIN SafetyVote_BallotAnswers ba ON ba.QuestionID=ep.QuestionID AND ba.OptionID=c.OptionID JOIN SafetyVote_Ballots b ON b.id=ba.BallotID AND b.CampaignVersionID=ep.CampaignVersionID AND b.Status='Accepted' WHERE ep.CampaignVersionID=? GROUP BY ep.PositionCode,c.id",[$c['CurrentVersionID']]);$abstentions=db_rows("SELECT ep.PositionCode positionCode,NULL candidateId,1 abstain,COUNT(*) count FROM SafetyVote_ElectionPositions ep JOIN SafetyVote_Ballots b ON b.CampaignVersionID=ep.CampaignVersionID AND b.Status='Accepted' LEFT JOIN SafetyVote_BallotAnswers ba ON ba.BallotID=b.id AND ba.QuestionID=ep.QuestionID WHERE ep.CampaignVersionID=? AND ep.AllowAbstain=1 AND ba.id IS NULL GROUP BY ep.PositionCode",[$c['CurrentVersionID']]);$counts=array_merge($counts,$abstentions);$n=db_row("SELECT (SELECT EligibleCount FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY id DESC LIMIT 1) eligible,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=? AND State='submitted') participation,(SELECT COUNT(*) FROM SafetyVote_Ballots WHERE CampaignVersionID=? AND Status='Accepted') accepted,(SELECT COUNT(*) FROM SafetyVote_BallotIdentities bi JOIN SafetyVote_Ballots b ON b.id=bi.BallotID WHERE b.CampaignVersionID=?) identities",array_fill(0,4,$c['CurrentVersionID']));return['positions'=>$positions,'counts'=>$counts,'eligibleCount'=>(int)($n['eligible']??0),'participationCount'=>(int)$n['participation'],'acceptedBallotCount'=>(int)$n['accepted'],'identityCount'=>(int)$n['identities']];}

function handle_safety_vote_phase6_routes(string$method,string$path):bool{
 if(strpos($path,'/safety-vote/')!==0)return false;$u=require_user();
 $config=route_params($path,'/safety-vote/admin/campaigns/:id/election');$certifier=route_params($path,'/safety-vote/admin/campaigns/:id/certifiers');$submit=route_params($path,'/safety-vote/campaigns/:id/ballot/submit');$recount=route_params($path,'/safety-vote/admin/campaigns/:id/results/recount');$cert=route_params($path,'/safety-vote/admin/campaigns/:id/results/:sid/certify-secret');$revoke=route_params($path,'/safety-vote/admin/campaigns/:id/results/:sid/revoke-certification');$publish=route_params($path,'/safety-vote/admin/campaigns/:id/results/:sid/publish');$void=route_params($path,'/safety-vote/admin/campaigns/:id/void');$results=route_params($path,'/safety-vote/campaigns/:id/results');
 if(!$config&&!$certifier&&!$submit&&!$recount&&!$cert&&!$revoke&&!$publish&&!$void&&!$results)return false;sv_require_schema();if($publish){$pc=sv6_campaign((int)$publish['id']);if(!$pc||$pc['CampaignType']!=='secret_election')return false;}if($config||$certifier||$recount||$cert||$revoke||$publish||$void){$required=['SafetyVote_ElectionPositions','SafetyVote_ElectionPositionCandidates','SafetyVote_CertifierAssignments','SafetyVote_ResultActions'];$marks=implode(',',array_fill(0,count($required),'?'));$found=db_rows("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ($marks)",$required);$v=db_row("SELECT SettingValue FROM SafetyVote_Settings WHERE SettingKey='schema_version'");if(count($found)!==count($required)||!in_array($v['SettingValue']??'',['2026-10-08-phase6-r1','2026-10-08-phase7-r1'],true))json_response(['success'=>false,'code'=>'SAFETY_VOTE_PHASE6_SCHEMA_NOT_READY'],503);}
 if($submit&&$method==='POST'){$c=sv6_campaign((int)$submit['id']);if(!$c||$c['CampaignType']!=='secret_election'||$c['PrivacyMode']!=='secret_ballot')return false;sv_require_permission($u,'SAFETY_VOTE_VIEW');global$config;$key=sv2_text($_SERVER['HTTP_IDEMPOTENCY_KEY']??'',160);if(strlen($key)<16)json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);$body=json_body();$pdo=db();$pdo->beginTransaction();try{$c=sv6_campaign((int)$submit['id'],true);if($c['Status']!=='Open'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT'],409);}$parsed=sv2_answers(sv2_questions((int)$c['CurrentVersionID']),$body['answers']??[]);$keyHash=hash_hmac('sha256',$key,(string)$config['jwt_secret']);$fingerprint=sv2_hash(['version'=>$body['campaignVersion']??null,'operation'=>'secret_ballot_submit','keyHash'=>$keyHash]);if(!$parsed['ok']||(int)($body['campaignVersion']??0)!==(int)$c['VersionNo']||($body['acknowledgedRules']??false)!==true){$pdo->rollBack();json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);}$replay=db_row("SELECT RequestFingerprint,ResponseReference FROM SafetyVote_RequestKeys WHERE CampaignVersionID=? AND ActorEmployeeID=? AND Operation='ballot_submit' AND RequestKeyHash=? FOR UPDATE",[$c['CurrentVersionID'],sv_actor($u),$keyHash]);if($replay){$pdo->rollBack();if($replay['RequestFingerprint']!==$fingerprint)json_response(['success'=>false,'code'=>'IDEMPOTENCY_CONFLICT'],409);json_response(['success'=>true,'data'=>['accepted'=>true,'receiptCode'=>$replay['ResponseReference'],'proof'=>'accepted_only','canLocateBallot'=>false,'replayed'=>true]]);}$eligible=db_row("SELECT e.SnapshotID FROM SafetyVote_EligibilitySnapshots es JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=es.id WHERE es.CampaignVersionID=? AND es.Status='frozen' AND e.EmployeeID=? AND e.EligibilityState='eligible' LIMIT 1 FOR UPDATE",[$c['CurrentVersionID'],sv_actor($u)]);if(!$eligible||db_row('SELECT id FROM SafetyVote_Participation WHERE CampaignVersionID=? AND EmployeeID=? FOR UPDATE',[$c['CurrentVersionID'],sv_actor($u)])){$pdo->rollBack();json_response(['success'=>false,'code'=>$eligible?'BALLOT_ALREADY_SUBMITTED':'CAMPAIGN_NOT_ELIGIBLE'],$eligible?409:403);}$receipt='SV-'.strtoupper(bin2hex(random_bytes(12)));$proof=sv6_receipt($receipt);$pdo->prepare("INSERT INTO SafetyVote_RequestKeys(CampaignVersionID,ActorEmployeeID,RequestKeyHash,Operation,RequestFingerprint,ResponseCode,ResponseReference,ExpiresAt) VALUES(?,?,?,'ballot_submit',?,200,?,DATE_ADD(NOW(),INTERVAL 7 DAY))")->execute([$c['CurrentVersionID'],sv_actor($u),$keyHash,$fingerprint,$receipt]);$pdo->prepare("INSERT INTO SafetyVote_Ballots(CampaignVersionID,PrivacyModeSnapshot,CanonicalBallotHash,IdempotencyHash,SchemaVersion) VALUES(?,'secret_ballot',?,?,?)")->execute([$c['CurrentVersionID'],sv2_hash($parsed['answers']),bin2hex(random_bytes(32)),SV6_CONTRACT]);$bid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE SafetyVote_Ballots SET BallotSequence=id WHERE id=?')->execute([$bid]);$a=$pdo->prepare('INSERT INTO SafetyVote_BallotAnswers(BallotID,QuestionID,OptionID,AnswerOrder) VALUES(?,?,?,?)');foreach($parsed['answers']as$row)foreach($row['optionIds']as$i=>$oid)$a->execute([$bid,$row['questionId'],$oid,$i+1]);$pdo->prepare("INSERT INTO SafetyVote_Participation(CampaignID,CampaignVersionID,SnapshotID,EmployeeID,State,AttemptCount,FirstStartedAt,SubmittedAt,LastActivityAt,ReceiptCodeHash) VALUES(?,?,?,?,'submitted',1,NOW(),NOW(),NOW(),?)")->execute([$c['id'],$c['CurrentVersionID'],$eligible['SnapshotID'],sv_actor($u),$proof['receiptHash']]);$pdo->commit();json_response(['success'=>true,'data'=>['accepted'=>true,'receiptCode'=>$receipt,'proof'=>'accepted_only','canLocateBallot'=>false,'canEdit'=>false]],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'BALLOT_SUBMIT_FAILED'],500);}}
 if($config&&$method==='PUT'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$c=sv6_campaign((int)$config['id']);$cfg=sv6_config(json_body());if(!$c||$c['CampaignType']!=='secret_election'||$c['PrivacyMode']!=='secret_ballot'||$c['Status']!=='Draft'||!$cfg['ok'])json_response(['success'=>false,'code'=>'ELECTION_STATE_CONFLICT','details'=>$cfg['errors']],409);$pdo=db();$pdo->beginTransaction();try{db_execute('DELETE epc FROM SafetyVote_ElectionPositionCandidates epc JOIN SafetyVote_ElectionPositions ep ON ep.id=epc.PositionID WHERE ep.CampaignVersionID=?',[$c['CurrentVersionID']]);db_execute('DELETE FROM SafetyVote_ElectionPositions WHERE CampaignVersionID=?',[$c['CurrentVersionID']]);foreach($cfg['positions']as$p){$q=db_row('SELECT id FROM SafetyVote_Questions WHERE id=? AND CampaignVersionID=?',[$p['questionId'],$c['CurrentVersionID']]);if(!$q)throw new RuntimeException('reference');db_execute('INSERT INTO SafetyVote_ElectionPositions(CampaignVersionID,QuestionID,PositionCode,Title,SeatCount,MaxSelections,AllowAbstain,TieRule,SortOrder,ConfigHash,CreatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$c['CurrentVersionID'],$p['questionId'],$p['positionCode'],$p['title'],$p['seatCount'],$p['maxSelections'],$p['allowAbstain']?1:0,$p['tieRule'],$p['sortOrder'],$cfg['configHash'],sv_actor($u)]);$pid=(int)$pdo->lastInsertId();foreach($p['candidateIds']as$i=>$cid){$candidate=db_row('SELECT c.id FROM SafetyVote_Candidates c JOIN SafetyVote_Options o ON o.id=c.OptionID WHERE c.id=? AND c.CampaignVersionID=? AND o.QuestionID=?',[$cid,$c['CurrentVersionID'],$p['questionId']]);if(!$candidate)throw new RuntimeException('candidate_reference');db_execute('INSERT INTO SafetyVote_ElectionPositionCandidates(PositionID,CandidateID,SortOrder) VALUES(?,?,?)',[$pid,$cid,$i+1]);}db_execute('UPDATE SafetyVote_Questions SET MinSelections=?,MaxSelections=?,RowVersion=RowVersion+1 WHERE id=?',[$p['allowAbstain']?0:1,$p['maxSelections'],$p['questionId']]);}$pdo->commit();json_response(['success'=>true,'data'=>$cfg]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'ELECTION_CONFIG_SAVE_FAILED'],500);}}
 if($certifier&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$c=sv6_campaign((int)$certifier['id']);$b=json_body();$emp=substr(trim((string)($b['employeeId']??'')),0,20);$role=$b['controlRole']??'';if(!$c||$c['Status']!=='Draft'||!in_array($role,['primary','secondary'],true)||!db_row('SELECT EmployeeID FROM Employees WHERE EmployeeID=?',[$emp]))json_response(['success'=>false,'code'=>'CERTIFIER_ASSIGNMENT_INVALID'],409);db_execute('INSERT INTO SafetyVote_CertifierAssignments(CampaignVersionID,EmployeeID,ControlRole,AssignedBy) VALUES(?,?,?,?)',[$c['CurrentVersionID'],$emp,$role,sv_actor($u)]);json_response(['success'=>true,'data'=>['employeeId'=>$emp,'controlRole'=>$role]],201);}
 if($recount&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_RESULT_VIEW');$c=sv6_campaign((int)$recount['id']);$reason=substr(trim((string)(json_body()['reason']??'')),0,1000);if(!$c||!in_array($c['Status'],['Closed','Counting'],true)||!$reason)json_response(['success'=>false,'code'=>'ELECTION_NOT_CLOSED'],409);$in=sv6_election_input($c);if($in['identityCount'])json_response(['success'=>false,'code'=>'SECRET_IDENTITY_INVARIANT_FAILED'],409);$out=sv6_calculate($in);if($out['reconciliationState']!=='balanced')json_response(['success'=>false,'code'=>'RECONCILIATION_FAILED'],422);$prior=db_row('SELECT * FROM SafetyVote_ResultSnapshots WHERE CampaignVersionID=? ORDER BY SnapshotNo DESC LIMIT 1',[$c['CurrentVersionID']]);$no=(int)($prior['SnapshotNo']??0)+1;db_execute("INSERT INTO SafetyVote_ResultSnapshots(CampaignID,CampaignVersionID,ParentSnapshotID,SnapshotNo,CalculationContract,CalculationRunType,Status,EligibleCount,ParticipationCount,AcceptedBallotCount,AbstainCount,QuorumState,TieState,ReconciliationState,InputHash,ResultHash,CalculatedBy,FrozenAt,FrozenBy) VALUES(?,?,?,?,?,'recount','Frozen',?,?,?,?,'met',?,'balanced',?,?,?,NOW(),?)",[$c['id'],$c['CurrentVersionID'],$prior['id']??null,$no,SV6_CONTRACT,$out['eligibleCount'],$out['participationCount'],$out['acceptedBallotCount'],$out['abstainCount'],$out['tieState'],$out['inputHash'],$out['resultHash'],sv_actor($u),sv_actor($u)]);$sid=(int)db()->lastInsertId();foreach($out['rows']as$row)db_execute("INSERT INTO SafetyVote_ResultRows(ResultSnapshotID,CandidateID,MetricKey,RawCount,RankNo,ResultState,MetadataJson) VALUES(?,?,'secret_count',?,?,?,?)",[$sid,$row['candidateId'],$row['count'],$row['rank'],$row['resultState'],json_encode(['positionCode'=>$row['positionCode']])]);db_execute("INSERT INTO SafetyVote_ResultActions(CampaignID,CampaignVersionID,ResultSnapshotID,PriorResultSnapshotID,ActionType,Reason,InputHash,ResultHash,RequestedBy,CompletedAt) VALUES(?,?,?,?,'recount',?,?,?,?,NOW())",[$c['id'],$c['CurrentVersionID'],$sid,$prior['id']??null,$reason,$out['inputHash'],$out['resultHash'],sv_actor($u)]);json_response(['success'=>true,'data'=>['snapshotId'=>$sid,'snapshotNo'=>$no]+$out],201);}
 if($cert&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_CERTIFY');$c=sv6_campaign((int)$cert['id']);$sid=(int)$cert['sid'];$b=json_body();$snap=db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? AND Status IN ('Frozen','Certified')",[$sid,$c['id']??0]);if(!$c||!$snap||$snap['ResultHash']!==($b['resultHash']??'')||$snap['ReconciliationState']!=='balanced'||$snap['TieState']!=='none'||!trim((string)($b['reason']??''))||!db_row('SELECT id FROM SafetyVote_CertifierAssignments WHERE CampaignVersionID=? AND EmployeeID=? AND IsActive=1',[$c['CurrentVersionID'],sv_actor($u)]))json_response(['success'=>false,'code'=>'CERTIFICATION_PRECONDITION_FAILED'],422);db_execute("INSERT INTO SafetyVote_Certifications(ResultSnapshotID,CertifierEmployeeID,CertificationRole,Decision,Reason,ResultHashSnapshot) VALUES(?,?,?,'certified',?,?)",[$sid,sv_actor($u),'dual_control',substr(trim((string)$b['reason']),0,1000),$snap['ResultHash']]);$state=sv6_certification(['resultHash'=>$snap['ResultHash'],'required'=>2,'certifications'=>array_map(fn($x)=>['employeeId'=>$x['CertifierEmployeeID'],'decision'=>$x['Decision'],'resultHash'=>$x['ResultHashSnapshot'],'revokedAt'=>$x['RevokedAt']],db_rows('SELECT * FROM SafetyVote_Certifications WHERE ResultSnapshotID=?',[$sid]))]);if($state['ready'])db_execute("UPDATE SafetyVote_ResultSnapshots SET Status='Certified' WHERE id=?",[$sid]);json_response(['success'=>true,'data'=>['snapshotId'=>$sid,'status'=>$state['ready']?'Certified':'AwaitingSecondCertifier']+$state],201);}
 if($revoke&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_CERTIFY');$b=json_body();$reason=substr(trim((string)($b['reason']??'')),0,1000);$n=db_execute('UPDATE SafetyVote_Certifications SET RevokedAt=NOW(),RevokedBy=?,RevokeReason=? WHERE ResultSnapshotID=? AND CertifierEmployeeID=? AND RevokedAt IS NULL',[sv_actor($u),$reason,(int)$revoke['sid'],sv_actor($u)]);if(!$n)json_response(['success'=>false,'code'=>'CERTIFICATION_NOT_ACTIVE'],409);db_execute("UPDATE SafetyVote_ResultSnapshots SET Status='Frozen' WHERE id=? AND Status IN ('Certified','Published')",[(int)$revoke['sid']]);db_execute("UPDATE SafetyVote_Campaigns SET Status='Closed',RowVersion=RowVersion+1 WHERE id=? AND Status='Published'",[(int)$revoke['id']]);json_response(['success'=>true,'data'=>['snapshotId'=>(int)$revoke['sid'],'status'=>'Frozen','publicationWithdrawn'=>true]]);}
 if($publish&&$method==='POST'){$c=sv6_campaign((int)$publish['id']);if(!$c||$c['CampaignType']!=='secret_election')return false;sv_require_permission($u,'SAFETY_VOTE_CERTIFY');$snap=db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? AND Status='Certified'",[(int)$publish['sid'],$c['id']]);if(!$snap)json_response(['success'=>false,'code'=>'DUAL_CERTIFICATION_REQUIRED'],422);$certs=array_map(fn($x)=>['employeeId'=>$x['CertifierEmployeeID'],'decision'=>$x['Decision'],'resultHash'=>$x['ResultHashSnapshot'],'revokedAt'=>$x['RevokedAt']],db_rows('SELECT * FROM SafetyVote_Certifications WHERE ResultSnapshotID=?',[$snap['id']]));if(!sv6_certification(['resultHash'=>$snap['ResultHash'],'certifications'=>$certs,'required'=>2])['ready'])json_response(['success'=>false,'code'=>'DUAL_CERTIFICATION_REQUIRED'],422);db_execute("UPDATE SafetyVote_ResultSnapshots SET Status='Published' WHERE id=?",[$snap['id']]);db_execute("UPDATE SafetyVote_Campaigns SET Status='Published',RowVersion=RowVersion+1 WHERE id=?",[$c['id']]);json_response(['success'=>true,'data'=>['snapshotId'=>(int)$snap['id'],'status'=>'Published','resultHash'=>$snap['ResultHash']]]);}
