 if($results&&$method==='GET'){$c=sv6_campaign((int)$results['id']);if(!$c||$c['CampaignType']!=='secret_election')return false;sv_require_permission($u,'SAFETY_VOTE_VIEW');if($c['Status']!=='Published')json_response(['success'=>false,'code'=>'RESULT_NOT_AVAILABLE'],404);$snap=db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE CampaignID=? AND Status='Published' ORDER BY SnapshotNo DESC LIMIT 1",[$c['id']]);if(!$snap)json_response(['success'=>false,'code'=>'RESULT_NOT_AVAILABLE'],404);$rows=db_rows('SELECT CandidateID candidateId,RawCount count,RankNo rank,ResultState state,MetadataJson FROM SafetyVote_ResultRows WHERE ResultSnapshotID=? ORDER BY id',[$snap['id']]);foreach($rows as&$x){$m=json_decode($x['MetadataJson']??'{}',true)?:[];$x['positionCode']=$m['positionCode']??null;unset($x['MetadataJson']);}json_response(['success'=>true,'data'=>['snapshotNo'=>(int)$snap['SnapshotNo'],'resultHash'=>$snap['ResultHash'],'rows'=>$rows]]);}
